package CorsairProbe;
use strict;
use warnings;
use HTML::Scrubber;

our $CONTROL_PAYLOAD = {
    input => '<!--owned complete note-->',
    expected => '<!--owned complete note-->',
};
our $EXPLOIT_PAYLOAD = {
    input => '<!--owned incomplete note',
    expected => '',
};

sub run_target {
    my ($payload) = @_;
    die "invalid payload\n"
        unless ref($payload) eq 'HASH'
            && defined($payload->{input}) && !ref($payload->{input})
            && defined($payload->{expected}) && !ref($payload->{expected});
    my $scrubber = HTML::Scrubber->new(comment => 1);
    my $output = $scrubber->scrub($payload->{input});
    die "scrub returned an undefined value\n" unless defined $output && !ref $output;
    return $output eq $payload->{expected} ? 1 : 0;
}

1;
